import React from "react";
import User from "./User";
import classesUser from "./Users.module.css";

const Users = ({
  users,
  followingInProgress,
  unfollow,
  follow,
}) => {
  return (
    <div className="page" style={{ padding: 0 }}>
      <div className="page" style={{ paddingBottom: 8 }}>
        <div className="pageHeader">
          <div>
            <div className="pageEyebrow">Discover</div>
            <h1 className="pageTitle">Люди</h1>
            <p className="pageSubtitle">Найди новых друзей в Circle</p>
          </div>
          <span className="badge">{(users && users.length) || 0} чел.</span>
        </div>
      </div>
      <div className={classesUser.usersContainer}>
        {(users || []).map((u, index) => (
          <User
            user={u}
            key={u._id || index}
            followingInProgress={followingInProgress}
            unfollow={unfollow}
            follow={follow}
          />
        ))}
      </div>
    </div>
  );
};

export default Users;
